from collections import defaultdict, deque

def parse(s): return [[int(x) for x in line.split()] for line in s.splitlines()]
def largest_components(grid):
 h,w=len(grid),len(grid[0]); seen=set(); best=defaultdict(int)
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   v=grid[r][c]; q=[(r,c)];seen.add((r,c));n=0
   while q:
    x,y=q.pop();n+=1
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==v:seen.add((a,b));q.append((a,b))
   best[v]=max(best[v],n)
 return sorted(best.items(),key=lambda x:-x[1])
